(function(){
  function parseCsv(s){ var rows=[],row=[],field='',i=0,inQ=false;
    while(i<s.length){ var c=s[i];
      if(inQ){ if(c==='"'){ if(s[i+1]==='"'){field+='"';i+=2;continue;} inQ=false;i++;continue; } field+=c;i++; }
      else { if(c==='"'){inQ=true;i++;continue;} if(c===','){row.push(field);field='';i++;continue;} if(c==='\r'){i++;continue;} if(c==='\n'){row.push(field);rows.push(row);row=[];field='';i++;continue;} field+=c;i++; } }
    row.push(field); rows.push(row); return rows; }
  function toMd(csv){ var rows=parseCsv(String(csv==null?'':csv)); if(rows.length===0) return {value:''};
    var header=rows[0]; var lines=['| '+header.join(' | ')+' |','| '+header.map(function(){return '---';}).join(' | ')+' |'];
    for(var i=1;i<rows.length;i++){ lines.push('| '+rows[i].join(' | ')+' |'); }
    return {value:lines.join('\n')}; }
  var API={toMd:toMd};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__CsvToMdForge__=API;
})();
